import math import numpy as np import baux
space = { "scale": baux.Log(1e-4, 1e-1), "phase": baux.Periodic(0.0, 2.0 * math.pi), "mixture": baux.Simplex(4), "kernel": baux.categorical(["matern", "rbf", "rational"]), } target = np.array([0.4, 0.3, 0.2, 0.1]) penalty = {"matern": 0.0, "rbf": 0.05, "rational": 0.1}
def objective(p): scale_err = (math.log10(p["scale"]) + 2.0) ** 2 phase_err = 1.0 - math.cos(p["phase"] - math.pi / 3.0) mix_err = float(np.sum((np.sqrt(p["mixture"]) - np.sqrt(target)) ** 2)) return -(scale_err + phase_err + mix_err + penalty[p["kernel"]])
state = baux.init(space, baux.turbo_enn(), key=baux.key(0)) state, batch = baux.ask(state, num_arms=4) y = np.array([objective(p) for p in batch.params]) state, mu = baux.tell(state, batch, y) print(state.best_params, state.best_y)
